edit('apps/web-storefront/lib/i18n.ts', 'website: the quotation texts (English and Arabic)', '  quote_brand: "Leap Auto Parts",', (s) => {
  const en = '  notifications: "Notifications",\n', ar = '  notifications: "الإشعارات",\n';
  if (s.split(en).length !== 2 || s.split(ar).length !== 2) return refuse('the "notifications" texts were not found once each');
  return s.replace(en, () => en + DATA.i18nEn).replace(ar, () => ar + DATA.i18nAr);
});
